//
// Helper code.
//

 void check_sysram_alignment ( unsigned addr ) {
      if ( ( addr % 16 ) != 0 ) {
            { std::ostringstream ss; ss    <<  "illegal operand sysram_mem_start_addr : 0x"  <<  hex  <<  addr  <<  " , SRAM memory start address should be a multiple of 16 for PDMA transfer." ; error(ss.str().c_str(),adl_get_current_pos(),adl_get_current_group()); } ;
        }
}

 void check_trans_type_sysram2opram ( unsigned type ) {
      if ( type == 1 ) {
            { std::ostringstream ss; ss    <<  "illegal pdma flex instruction, trans_type is .opram2sysram but operands match the SYSRAM to OPRAM version" ; error(ss.str().c_str(),adl_get_current_pos(),adl_get_current_group()); } ;
        }
}

 void check_trans_type_vs_decomp_var ( unsigned type , unsigned decomp_value ) {
      if ( type == 0 && decomp_value == 0 ) {
            { std::ostringstream ss; ss    <<  "illegal pdma flex instruction, trans_type is .sysram2opram but operands match the OPRAM to SYSRAM version" ; error(ss.str().c_str(),adl_get_current_pos(),adl_get_current_group()); } ;
        }
      if ( type == 1 && decomp_value != 0 ) {
            { std::ostringstream ss; ss    <<  "illegal pdma flex instruction, trans_type is .opram2sysram but operands match a SYSRAM to OPRAM version" ; error(ss.str().c_str(),adl_get_current_pos(),adl_get_current_group()); } ;
        }
}

 unsigned decode_bank ( unsigned addr ) {
      if ( addr & 0xc000 ) {
            return ( addr & 0x8000 ) ? ( ( addr >> 13 ) & 0x3 ) : ( ( addr >> 12 ) & 0x3 ) ;
        }
      return 8 ;
}

 unsigned decode_column ( unsigned addr ) {
      if ( addr & 0xc000 ) {
            return ( addr & 0x8000 ) ? ( ( addr >> 4 ) & 0x1ff ) : ( ( addr >> 4 ) & 0xff ) ;
        }
      return 512 ;
}

 unsigned decode_mem ( unsigned addr ) {
      if ( addr & 0xc000 ) {
            return ( addr & 0x8000 ) ? 2 : 1 ;
        } else if ( addr < 0x1034 ) {
            if ( addr < 0x40 ) {
                  return 0 ;
              } else if ( ( 0x1000 <= addr ) && ( addr <= 0x100e ) ) {
                  return 3 ;
              } else if ( ( ( 0x1010 <= addr ) && ( addr <= 0x1015 ) ) || ( addr >= 0x1030 ) ) {
                  return 4 ;
              } else if ( ( 0x1016 <= addr ) && ( addr <= 0x101f ) ) {
                  return 5 ;
              } else if ( ( 0x1020 <= addr ) && ( addr <= 0x1027 ) ) {
                  return 6 ;
              }
            return 7 ;
        }
      return 7 ;
}

 unsigned decode_slice ( unsigned addr ) {
      if ( addr & 0xc000 ) {
            return ( addr & 0xf ) ;
        }
      return ( addr & 0x3f ) ;
}

 std :: string get_mem_name ( unsigned x ) {
       unsigned m = decode_mem ( x ) ;
       ostringstream s ;
      switch ( m ) {
            case 0 : s << "WR_" << decode_slice ( x ) ;
            break ;
            case 1 : s << "TR_" << decode_bank ( x ) << "_" << decode_column ( x ) << "_" << decode_slice ( x ) ;
            break ;
            case 2 : s << "OR_" << decode_bank ( x ) << "_" << decode_column ( x ) << "_" << decode_slice ( x ) ;
            break ;
            case 3 : s << "SPR_" << decode_slice ( x ) ;
            break ;
            case 4 : if ( 0x1030 <= x && x <= 0x1033 ) {
                  s << "HW_SPR_" << ( decode_slice ( x ) - 0x30 + 6 ) ;
              } else {
                  s << "HW_SPR_" << ( decode_slice ( x ) - 0x10 ) ;
              }
            break ;
            case 5 : s << "EVT_SPR_" << ( decode_slice ( x ) - 0x16 ) ;
            break ;
            case 6 : s << "CHRP_SPR_" << ( decode_slice ( x ) - 0x20 ) ;
            break ;
            default : s << "0x" << hex << x << " (reserved)" ;
        }
      return s . str (  ) ;
}

 unsigned get_mode ( unsigned x ) {
      return x >> 14 ;
}


